mapper.select:
SELECT fs.pressure_level FROM finance_cashflow_forecast_snapshot fs WHERE 1=1
AND fs.dept_id = #{deptId}
ORDER BY fs.forecast_date DESC LIMIT 1

SELECT * FROM ( -- 1. SLEEPING_HIGH_VALUE: 成长值 >= 500 且 last_active_time >= 30 天 SELECT m.member_id AS memberId, m.member_no AS memberNo, m.member_name AS memberName, m.dept_id AS deptId, d.dept_name AS deptName, 'SLEEPING_HIGH_VALUE' AS segmentType, m.growth_value AS growthValue, m.card_type AS cardType, ct.type_name AS cardTypeName, m.last_active_time AS lastActiveTime, DATEDIFF(NOW(), m.last_active_time) AS activeDaysAgo, CASE WHEN EXISTS( SELECT 1 FROM fin_sale_record r WHERE r.member_id = m.member_id AND r.sale_date >= DATE_SUB(NOW(), INTERVAL 30 DAY) AND r.del_flag = '0' ) THEN TRUE ELSE FALSE END AS recentRepurchased, (SELECT COUNT(*) FROM mem_member_sign_in si WHERE si.member_id = m.member_id AND si.sign_date >= DATE_SUB(CURDATE(), INTERVAL 30 DAY) ) AS recentSignInCount, CONCAT('成长值', m.growth_value, '，', DATEDIFF(NOW(), m.last_active_time), '天未活跃') AS candidateReason FROM mem_member m LEFT JOIN sys_dept d ON m.dept_id = d.dept_id LEFT JOIN mem_member_card_type ct ON m.card_type = ct.type_code AND ct.status = '0' AND ct.del_flag = '0' WHERE m.del_flag = '0' AND m.status = '0' AND m.growth_value >= 500 AND m.last_active_time IS NOT NULL AND DATEDIFF(NOW(), m.last_active_time) >= 30
AND m.dept_id = #{params.deptId}
UNION ALL
-- 2. NEAR_LEVEL_UP: 距下一等级成长值 <= 100 且 last_active_time <= 45 天 SELECT m.member_id AS memberId, m.member_no AS memberNo, m.member_name AS memberName, m.dept_id AS deptId, d.dept_name AS deptName, 'NEAR_LEVEL_UP' AS segmentType, m.growth_value AS growthValue, m.card_type AS cardType, ct.type_name AS cardTypeName, m.last_active_time AS lastActiveTime, DATEDIFF(NOW(), m.last_active_time) AS activeDaysAgo, CASE WHEN EXISTS( SELECT 1 FROM fin_sale_record r WHERE r.member_id = m.member_id AND r.sale_date >= DATE_SUB(NOW(), INTERVAL 30 DAY) AND r.del_flag = '0' ) THEN TRUE ELSE FALSE END AS recentRepurchased, (SELECT COUNT(*) FROM mem_member_sign_in si WHERE si.member_id = m.member_id AND si.sign_date >= DATE_SUB(CURDATE(), INTERVAL 30 DAY) ) AS recentSignInCount, CONCAT('距下一等级差', (next_ct.min_growth - m.growth_value), '成长值') AS candidateReason FROM mem_member m LEFT JOIN sys_dept d ON m.dept_id = d.dept_id LEFT JOIN mem_member_card_type ct ON m.card_type = ct.type_code AND ct.status = '0' AND ct.del_flag = '0' LEFT JOIN mem_member_card_type next_ct ON next_ct.status = '0' AND next_ct.del_flag = '0' AND next_ct.min_growth = ( SELECT MIN(min_growth) FROM mem_member_card_type WHERE min_growth > COALESCE(ct.min_growth, 0) AND status = '0' AND del_flag = '0' ) WHERE m.del_flag = '0' AND m.status = '0' AND m.last_active_time IS NOT NULL AND DATEDIFF(NOW(), m.last_active_time) <= 45 AND next_ct.min_growth IS NOT NULL AND (next_ct.min_growth - m.growth_value) <= 100 AND (next_ct.min_growth - m.growth_value) > 0
AND m.dept_id = #{params.deptId}
UNION ALL
-- 3. RECENT_ACTIVE_NO_REPEAT: 近 30 天活跃但近 30 天无复购 SELECT m.member_id AS memberId, m.member_no AS memberNo, m.member_name AS memberName, m.dept_id AS deptId, d.dept_name AS deptName, 'RECENT_ACTIVE_NO_REPEAT' AS segmentType, m.growth_value AS growthValue, m.card_type AS cardType, ct.type_name AS cardTypeName, m.last_active_time AS lastActiveTime, DATEDIFF(NOW(), m.last_active_time) AS activeDaysAgo, FALSE AS recentRepurchased, (SELECT COUNT(*) FROM mem_member_sign_in si WHERE si.member_id = m.member_id AND si.sign_date >= DATE_SUB(CURDATE(), INTERVAL 30 DAY) ) AS recentSignInCount, '近30天活跃但无复购' AS candidateReason FROM mem_member m LEFT JOIN sys_dept d ON m.dept_id = d.dept_id LEFT JOIN mem_member_card_type ct ON m.card_type = ct.type_code AND ct.status = '0' AND ct.del_flag = '0' WHERE m.del_flag = '0' AND m.status = '0' AND m.last_active_time IS NOT NULL AND DATEDIFF(NOW(), m.last_active_time) <= 30 AND NOT EXISTS ( SELECT 1 FROM fin_sale_record r WHERE r.member_id = m.member_id AND r.sale_date >= DATE_SUB(NOW(), INTERVAL 30 DAY) AND r.del_flag = '0' )
AND m.dept_id = #{params.deptId}
UNION ALL
-- 4. PRESSURE_STORE_RECALL: 门店现金压力 HIGH/CRITICAL 且 last_active 15-90 天 SELECT m.member_id AS memberId, m.member_no AS memberNo, m.member_name AS memberName, m.dept_id AS deptId, d.dept_name AS deptName, 'PRESSURE_STORE_RECALL' AS segmentType, m.growth_value AS growthValue, m.card_type AS cardType, ct.type_name AS cardTypeName, m.last_active_time AS lastActiveTime, DATEDIFF(NOW(), m.last_active_time) AS activeDaysAgo, CASE WHEN EXISTS( SELECT 1 FROM fin_sale_record r WHERE r.member_id = m.member_id AND r.sale_date >= DATE_SUB(NOW(), INTERVAL 30 DAY) AND r.del_flag = '0' ) THEN TRUE ELSE FALSE END AS recentRepurchased, (SELECT COUNT(*) FROM mem_member_sign_in si WHERE si.member_id = m.member_id AND si.sign_date >= DATE_SUB(CURDATE(), INTERVAL 30 DAY) ) AS recentSignInCount, CONCAT('门店现金压力', fs.pressure_level, '，需优先召回') AS candidateReason FROM mem_member m LEFT JOIN sys_dept d ON m.dept_id = d.dept_id LEFT JOIN mem_member_card_type ct ON m.card_type = ct.type_code AND ct.status = '0' AND ct.del_flag = '0' INNER JOIN finance_cashflow_forecast_snapshot fs ON fs.dept_id = m.dept_id AND fs.forecast_date = ( SELECT MAX(forecast_date) FROM finance_cashflow_forecast_snapshot WHERE dept_id = m.dept_id ) AND fs.pressure_level IN ('HIGH', 'CRITICAL') WHERE m.del_flag = '0' AND m.status = '0' AND m.last_active_time IS NOT NULL AND DATEDIFF(NOW(), m.last_active_time) BETWEEN 15 AND 90
AND m.dept_id = #{params.deptId}
) AS combined WHERE 1=1
AND segmentType = #{params.segmentType}
ORDER BY CASE segmentType WHEN 'PRESSURE_STORE_RECALL' THEN 1 WHEN 'SLEEPING_HIGH_VALUE' THEN 2 WHEN 'NEAR_LEVEL_UP' THEN 3 WHEN 'RECENT_ACTIVE_NO_REPEAT' THEN 4 ELSE 5 END, growthValue DESC LIMIT 50

SELECT a.action_id AS actionId, a.action_no AS actionNo, a.dept_id AS deptId, a.dept_name AS deptName, a.action_type AS actionType, a.action_title AS actionTitle, a.pressure_level AS pressureLevel, a.candidate_count AS candidateCount, a.executed_count AS executedCount, a.status, a.action_reason AS actionReason, a.suggested_script AS suggestedScript, a.create_time AS createTime FROM mem_growth_action a WHERE a.del_flag = '0'
AND a.dept_id = #{params.deptId}
AND a.action_type = #{params.actionType}
AND a.status = #{params.status}
ORDER BY a.create_time DESC LIMIT 20

SELECT COUNT(*) FROM mem_growth_action
WHERE del_flag = '0' AND status = 'PENDING'

    AND dept_id = #{params.deptId}

SELECT COUNT(*) FROM mem_growth_action_member
WHERE action_id = #{actionId}
  AND execute_status IN ('DONE', 'IGNORED')

SELECT COUNT(*) AS totalMemberCount, SUM(CASE WHEN repurchased = '1' THEN 1 ELSE 0 END) AS repurchaseMemberCount, SUM(CASE WHEN signed_in = '1' THEN 1 ELSE 0 END) AS signInMemberCount, SUM(CASE WHEN growth_increased = '1' THEN 1 ELSE 0 END) AS growthIncreasedMemberCount, SUM(CASE WHEN repurchased = '1' OR signed_in = '1' OR growth_increased = '1' THEN 1 ELSE 0 END) AS effectiveMemberCount FROM mem_growth_action_member am INNER JOIN mem_growth_action a ON am.action_id = a.action_id AND a.del_flag = '0' WHERE 1=1
AND am.dept_id = #{params.deptId}
AND a.status = #{params.status}
